function portrait(name){if(name==='Marian')return marianPortrait();const c=document.createElement('canvas');c.width=c.height=54;const p=c.getContext('2d'),colors=palettes[name]||['#d4df9f','#53695a'];p.fillStyle='#c9d7b7';p.fillRect(0,0,54,54);p.fillStyle=colors[0];p.fillRect(9,36,36,20);p.fillStyle=colors[1];p.beginPath();p.arc(27,23,18,0,7);p.fill();p.fillStyle='#d2a17e';p.beginPath();p.arc(27,25,13,0,7);p.fill();p.fillStyle=colors[1];p.fillRect(12,10,30,10);p.fillStyle='#2e4238';p.fillRect(21,24,2,3);p.fillRect(31,24,2,3);p.fillRect(24,33,7,2);return c.toDataURL();}
