function showNextDialogue(){if(activeDialogue||!dialogueQueue.length)return;activeDialogue={...dialogueQueue.shift(),until:storyClock};activeDialogue.until+=activeDialogue.duration;const band=$('#bubble');band.replaceChildren();const img=document.createElement('img');img.src=portrait(activeDialogue.who);img.alt='';const block=document.createElement('div'),name=document.createElement('strong'),line=document.createElement('p');name.textContent=activeDialogue.who;line.textContent=activeDialogue.text;block.append(name,line);band.append(img,block);band.hidden=false;}
