function updateNotices(dt){const node=$('#banner');if(mode!=='play'){node.hidden=true;return;}if((worldSpeechPending()||activeDialogue)&&!noticeQueue.some(n=>n.kind==='confirmation')&&activeNotice?.kind!=='confirmation'){node.hidden=true;return;}if(activeNotice){if(!activeNotice.layoutBlocked)activeNotice.remaining-=dt;if(activeNotice.remaining<=0)activeNotice=null;}if(!activeNotice&&noticeQueue.length){const priority=noticeQueue.findIndex(n=>n.kind==='confirmation');activeNotice={...noticeQueue.splice(priority<0?0:priority,1)[0]};activeNotice.remaining=activeNotice.duration;node.dataset.kind=activeNotice.kind;node.replaceChildren(document.createTextNode(activeNotice.title));const small=document.createElement('small');small.textContent=activeNotice.sub;node.append(small);}node.hidden=!activeNotice;if(activeNotice){const r=canvas.getBoundingClientRect(),w=Math.min(300,r.width-24),h=node.offsetHeight||64,spot=messageSpot(w,h,r.width,r.height,r.width/2,r.height/2);node.style.left=spot.x+'px';node.style.top=spot.y+'px';node.style.width=w+'px';node.hidden=!spot.fits;activeNotice.layoutBlocked=!spot.fits;if(activeNotice.kind==='confirmation'){node.hidden=true;activeNotice.layoutBlocked=false;}}}
function burst(x,y,color,count=12){for(let i=0;i<count;i++)particles.push({x,y,vx:Math.cos(i*2.4)*60,vy:Math.sin(i*2.4)*60-20,life:.65+Math.random()*.4,max:1,color});}
