function progress(){let value=0,max=3,label='';if(level===0){value=m.cycles;label=m.cycles===3?'Tres ciclos completados':`Ciclo ${m.cycles+1}: documentos → Ventas → Operaciones → Recaudación`;}if(level===1){value=m.caught?1:0;max=1;label=m.caught?'¡Capturado!':'Persecución';}if(level===2){max=9;value=movingCount();label=`Mudanza: ${value}/9 · Tus cajas: ${m.boxes}/3`;}if(level===3){max=2;value=m.cards.length;label=value===2?'Salida desbloqueada · acércate a la puerta':'Identificaciones';}if(level===4){value=m.phase;label=['Cobertura','Decoración','Velas','Torta terminada'][value];}$('#task-label').textContent=label;$('#task-count').textContent=`${value}/${max}`;$('#task-fill').style.width=`${value/max*100}%`;$('#task-meter').classList.toggle('confirmed',taskFlash>0);$('#task-meter').setAttribute('aria-valuenow',String(value));$('#task-meter').setAttribute('aria-valuemax',String(max));}
