function loadLevel(i,resume=null){noticeQueue=[];activeNotice=null;mode='play';$('#arena').classList.remove('celebrating','epilogue','party-scene');$('#party-actions').hidden=true;$('#arena').classList.toggle('office-bubbles',i===0);level=i;$('#arena').classList.toggle('sweet-scene',i===4);t=resume?clamp(resume.t,0,ARCADE_LEVELS[i].duration):0;m=resume?.m||freshModel(i);player=resume?.player||{x:i===1?100:i===3?112:380,y:i===3?184:360};jose=resume?.jose||{x:player.x-35,y:player.y+22};particles=[];trail=[];target=null;hit=0;actCooldown=0;taskFlash=0;transitionLeft=resume?.transitionLeft??null;stageStart=t;lastSave=t;running=true;paused=false;finished=false;keys.clear();joy={x:0,y:0};actionHeld=false;clearMovementPointer();actionPointer=null;$('#bubble').hidden=true;$('#overlay').hidden=true;$('#touch').hidden=false;$('#hud').hidden=false;$('#memory').hidden=true;$('#banner').hidden=true;$('#pause').textContent='Ⅱ';$('#level-name').textContent=`${i+1} / 5 · ${ARCADE_LEVELS[i].name}`;$('#progress').textContent=`${i+1} — 5 · ${ARCADE_LEVELS[i].name.toUpperCase()}`;$('#objective').textContent=ARCADE_LEVELS[i].goal;$('#tip').textContent=ARCADE_LEVELS[i].tip;updateMission();progress();if(i===0)prepareOfficeSpeech();if(i!==0){const pending=[...(activeDialogue?[{...activeDialogue,duration:Math.max(4.5,activeDialogue.until-storyClock)}]:[]),...dialogueQueue];activeDialogue=null;dialogueQueue=[];for(const entry of pending){const actor=entry.who==='José'?'jose':entry.who==='Marian'?'marian':'player';worldSpeech(actor,entry.who,entry.text,'pending-'+entry.who+entry.text);}}resize();updateActionUI();save();}
function startFresh(){mode='play';score=0;unlocked=0;supplies=[];storyClock=0;dialogueQueue=[];activeDialogue=null;seenMessages.clear();$('#bubble').hidden=true;loadLevel(0);beginPreamble();}
function title(){mode='title';running=false;$('#hud').hidden=true;$('#touch').hidden=true;$('#bubble').hidden=true;$('#banner').hidden=true;$('#memory').hidden=true;$('#mission').hidden=true;$('#overlay').hidden=false;$('#overlay').innerHTML=`<div class="panel"><span class="eyebrow">OPERACIÓN: LA TORTA DE INDIRA</span><h1>Sobrevivimos<br>de <em>milagro.</em></h1><p>José y Marian preparan una sorpresa de cumpleaños para Indira. Primero hay que sobrevivir a la oficina… y salvar la torta.</p><p class="controls">MÓVIL: mantén pulsado con el dedo hacia donde quieras moverte. Suelta para detenerte.<br>ORDENADOR: flechas / WASD + espacio / E</p><nav>${restored&&!restored.finished?'<button id="resume">Retomar aventura →</button>':''}<button id="start" ${restored&&!restored.finished?'class="secondary"':''}>Comenzar aventura</button>${restored?.finished?'<button id="remember" class="secondary">Ver felicitación</button>':''}</nav><p class="fine">Cinco niveles · Unos seis minutos, a tu ritmo · Puedes terminar antes<br>Personajes provisionales, sin parecido real.</p></div>`;$('#start').onclick=startFresh;if($('#resume'))$('#resume').onclick=()=>{score=restored.score||0;unlocked=restored.unlocked||0;supplies=restored.supplies||[];storyClock=restored.storyClock||0;dialogueQueue=restored.dialogueQueue||[];activeDialogue=restored.activeDialogue||null;if(activeDialogue){dialogueQueue.unshift({...activeDialogue,duration:Math.max(3,activeDialogue.until-storyClock)});activeDialogue=null;}loadLevel(restored.level,restored);if(restored.mode==='preamble')beginPreamble(restored.introTime||0);else if(restored.mode==='mission')openMission(restored.pendingLevel||0);else if(restored.mode==='chat')openRoboChat(restored.chatTime||0);else if(restored.mode==='mail'){mailElapsed=restored.mailElapsed||0;openMail(restored.mailIndex||0,true);}else if(restored.mode==='rescue')beginRescue(restored.rescueTime||0);else showNextDialogue();};if($('#remember'))$('#remember').onclick=()=>{score=restored.score||0;photoIndex=restored.photoIndex||0;if(restored.epilogueScreen==='letter')showLetter();else showMemories();};}
function ending(){beginParty();}
function setPause(value){if(!running)return;paused=value;clearInputs();paintPointer=null;$('#pause').textContent=value?'▶':'Ⅱ';if(value){save();$('#overlay').hidden=false;$('#overlay').innerHTML='<div class="panel"><h1>Pausa corporativa.</h1><p>El tiempo y la historia están detenidos.</p><button id="return">Volver →</button></div>';$('#return').onclick=()=>setPause(false);}else if(mode==='preamble'){renderPreamble();$('#overlay').hidden=false;}else if(mode==='mission'){renderMission();$('#overlay').hidden=false;}else if(mode==='chat'){renderRoboChat();$('#overlay').hidden=false;}else if(mode==='mail'){renderMail();$('#overlay').hidden=false;}else $('#overlay').hidden=true;}
$('#pause').onclick=()=>setPause(!paused);$('#brand').onclick=e=>{e.preventDefault();if(running)setPause(!paused);};document.addEventListener('visibilitychange',()=>{if(document.hidden)setPause(true);});window.addEventListener('blur',()=>{if(running)setPause(true);});window.addEventListener('pagehide',save);
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','w','a','s','d','e'].includes(k)&&running&&!paused&&mode==='play'){e.preventDefault();if(!keys.has(k)&&(k===' '||k==='e'))actionPress();keys.add(k);}if(k==='escape'&&!e.repeat)setPause(!paused);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function clearMovementPointer(){const previous=movePointer;movePointer=null;movePoint=null;target=null;if(previous!==null)try{canvas.releasePointerCapture?.(previous);}catch{}}
function releaseScenePointer(e){if(e.pointerId===movePointer)clearMovementPointer();if(e.pointerId===paintPointer){paintPointer=null;actionHeld=false;}}
$('#action').onpointerdown=e=>{if(!running||paused||mode!=='play'||transitionLeft!==null||$('#action').disabled)return;e.preventDefault();actionPointer=e.pointerId;$('#action').setPointerCapture(e.pointerId);actionHeld=true;actionPress();};
function releaseActionPointer(e){if(e.pointerId!==actionPointer)return;actionPointer=null;actionHeld=false;}
for(const ev of ['onpointerup','onpointercancel','onlostpointercapture'])$('#action')[ev]=releaseActionPointer;
function pointerWorld(e){const r=canvas.getBoundingClientRect();return {x:((e.clientX-r.left)/r.width*vw-(worldWidth()>800?0:viewShiftX))/worldZoom+camera,y:((e.clientY-r.top)/r.height*vh-offsetY)/worldZoom};}
canvas.onpointerdown=e=>{if(!running||paused||mode!=='play'||transitionLeft!==null)return;if(e.pointerType==='touch'||e.pointerType==='pen'){if(movePointer!==null)return;e.preventDefault();movePointer=e.pointerId;movePoint={clientX:e.clientX,clientY:e.clientY};target=null;canvas.setPointerCapture(e.pointerId);$('#arena').classList.add('touch-controls');return;}const p=pointerWorld(e);if(level===4&&dist(player,cake)<120&&dist(p,cake)<110){e.preventDefault();paintPointer=e.pointerId;canvas.setPointerCapture(e.pointerId);actionHeld=true;actionPress();}else target=p;};
canvas.onpointermove=e=>{if(e.pointerId!==movePointer)return;e.preventDefault();movePoint={clientX:e.clientX,clientY:e.clientY};};
for(const ev of ['onpointerup','onpointercancel','onlostpointercapture'])canvas[ev]=releaseScenePointer;
window.addEventListener('pointerup',releaseScenePointer);window.addEventListener('pointercancel',releaseScenePointer);
function updateActionUI(){$('#touch').hidden=mode!=='play'||level!==4;const action=$('#action'),bakery=mode==='play'&&level===4,near=bakery&&dist(player,cake)<120,ready=near&&transitionLeft===null&&m.phase<3;$('#arena').classList.toggle('bakery-controls',bakery);action.classList.toggle('cake-ready',ready);action.disabled=bakery&&!ready;const label=bakery?(ready?'DECORAR TORTA':m.phase===3?'¡TORTA LISTA!':'ACÉRQUESE A LA TORTA'):'ACTUAR';const hint=bakery?(m.phase===0?'Mantén pulsado para cubrir':m.phase===1?`Pulsa: decoración ${m.toppings}/3`:'Pulsa para colocar las velas'):'Espacio / E';if(action.dataset.label!==label||action.dataset.hint!==hint){action.textContent=label;const small=document.createElement('span');small.textContent=hint;action.append(small);action.dataset.label=label;action.dataset.hint=hint;action.setAttribute('aria-label',label+'. '+hint);}}
function resize(){clearMovementPointer();const r=canvas.getBoundingClientRect();if(r.width<=0||r.height<=0)return;vw=r.width<650?460:800;vh=vw*r.height/r.width;const inset=vh<560?Math.min(70,vh*.23):0;worldZoom=Math.min(1,(vh-inset)/560);viewShiftX=Math.max(0,(vw-800*worldZoom)/2);offsetY=$('#arena').classList.contains('normal-play')?0:inset+(vh-inset-560*worldZoom)/2;$('#arena').classList.toggle('touch-controls',!!window.matchMedia?.('(pointer: coarse)').matches||r.width<650||r.height<500&&r.width<1000);dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(vw*dpr);canvas.height=Math.round(vh*dpr);}
window.addEventListener('resize',resize);resize();
function solids(){if(level===3){const out=[];mazeRows.forEach((row,y)=>[...row].forEach((c,x)=>{if(c==='1')out.push({x:40+x*48,y:112+y*48,w:48,h:48});}));return out;}if(level===0)return [{x:592,y:168,w:96,h:36},{x:110,y:145,w:110,h:40}];return [];}
function blocked(x,y){return solids().some(r=>x+11>r.x&&x-11<r.x+r.w&&y+9>r.y&&y-9<r.y+r.h);}
function mazeRoute(start,goal){const a=[clamp(Math.floor((start.x-40)/48),1,13),clamp(Math.floor((start.y-112)/48),1,7)],b=[Math.floor((goal.x-40)/48),Math.floor((goal.y-112)/48)],queue=[a],seen=new Map([[a.join(','),null]]);let found=null;for(let i=0;i<queue.length;i++){const p=queue[i];if(p[0]===b[0]&&p[1]===b[1]){found=p;break;}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const n=[p[0]+dx,p[1]+dy],k=n.join(',');if(n[0]>0&&n[0]<14&&n[1]>0&&n[1]<8&&mazeRows[n[1]][n[0]]==='0'&&!seen.has(k)){seen.set(k,p);queue.push(n);}}}const route=[];while(found){route.unshift({x:64+found[0]*48,y:136+found[1]*48});found=seen.get(found.join(','));}return route;}
function focusPoint(){if(level===0)return m.step===0?{...(cycleDocs().find((p,i)=>!m.docs.includes(i))||receipts[0]),label:'DOCUMENTOS'}:{...officeStations[Math.min(2,m.step-1)],label:officeStations[Math.min(2,m.step-1)].name};if(level===1)return {...mohamed(),label:'MOHAMED'};if(level===2)return {...(m.carrying?movingDestination('Indira'):m.cargo.find(c=>c.owner==='Indira'&&c.state==='waiting')||movingDestination('Indira')),label:m.carrying?'ENTREGA':'TUS CAJAS'};if(level===3)return m.cards.length===2?{...exit,label:'SALIDA'}:{...cards[m.cards.includes(0)?1:0],label:'ID'};return {...cake,label:'TORTA'};}
function move(dx,dy,dt){let speed=level===2&&m.carrying?(m.boxes===1?160:185):220;if(level===1&&m.dash>0)speed=380;speed*=hit>.7?.5:1;const nx=clamp(player.x+dx*speed*dt,24,worldWidth()-24),ny=clamp(player.y+dy*speed*dt,level===3?125:110,level===3?525:495);if(!blocked(nx,player.y))player.x=nx;if(!blocked(player.x,ny))player.y=ny;walk+=Math.hypot(dx,dy)*dt*11;}
function hazard(x,y,r=22){if(hit<=0&&Math.hypot(player.x-x,player.y-y)<r+12){hit=1;if(level===2)dropCarriedBox();burst(player.x,player.y,'#f2d5b1',8);if(level!==1&&storyClock-lastHazardSpeech>12){lastHazardSpeech=storyClock;say('Indira','¡Cuidado con los carritos!');}}}
function mohamed(){return {x:m.x||310,y:m.y||290};}
function actionPress(){if(!running||paused||mode!=='play'||transitionLeft!==null||actCooldown>0)return;actCooldown=.3;
 if(level===0)deliverOffice();
 if(level===1){if(dist(player,mohamed())<95){finishLevel();}else if(m.dashCooldown<=0){m.dash=.65;m.dashCooldown=3;burst(player.x,player.y,'#dbe3ae',8);}}
 if(level===2)actMoving();
 if(level===4&&dist(player,cake)<120){if(m.phase===1){m.toppings++;burst(cake.x+Math.cos(m.toppings*2)*35,cake.y,'#e27780',10);if(m.toppings>=3){m.phase=2;taskDone('Decoración lista');}}else if(m.phase===2){m.lit=true;m.phase=3;taskDone('Velas encendidas');finishLevel();}}
}
