function messageSpot(w,h,width,height,ax,ay){
 const base=canvas.getBoundingClientRect(),obstacles=['#hud','#action','#mission','#debt-meter'].map(id=>$(id)).filter(n=>!n.hidden&&n.getBoundingClientRect).map(n=>{const r=n.getBoundingClientRect();return {x:r.left-base.left-8,y:r.top-base.top-8,w:r.width+16,h:r.height+16};});
 const valid=(x,y)=>x>=8&&y>=8&&x+w<=width-8&&y+h<=height-8&&!obstacles.some(r=>x<r.x+r.w&&x+w>r.x&&y<r.y+r.h&&y+h>r.y);
 const candidates=[{x:clamp(ax-w/2,8,width-w-8),y:clamp(ay-h-15,8,height-h-8)}];
 if(valid(candidates[0].x,candidates[0].y))return {...candidates[0],fits:true};for(let y=8;y<=height-h-8;y+=8)for(let x=8;x<=width-w-8;x+=12)candidates.push({x,y});
 const available=candidates.filter(p=>valid(p.x,p.y)).sort((a,b)=>Math.hypot(a.x+w/2-ax,a.y+h-ay)-Math.hypot(b.x+w/2-ax,b.y+h-ay));return available.length?{...available[0],fits:true}:{x:8,y:8,fits:false};
}
