function initializeEpilogue(){const actions=document.createElement('div');actions.id='party-actions';actions.hidden=true;actions.innerHTML='<span>Indira · José · Marian · Julito</span><button id="party-memories">Ver nuestros recuerdos →</button>';$('#arena').append(actions);$('#party-memories').onclick=showMemories;
 const lightbox=document.createElement('dialog');lightbox.id='photo-lightbox';lightbox.setAttribute('aria-label','Fotografía ampliada');lightbox.innerHTML='<div class="lightbox-toolbar"><button id="lightbox-prev" aria-label="Fotografía anterior">←</button><span id="lightbox-count"></span><button id="lightbox-next" aria-label="Fotografía siguiente">→</button><button id="lightbox-close">Cerrar ✕</button></div><img id="lightbox-photo" alt="">';document.body.append(lightbox);$('#lightbox-close').onclick=()=>lightbox.close();$('#lightbox-prev').onclick=()=>changePhoto(-1);$('#lightbox-next').onclick=()=>changePhoto(1);lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close();});window.addEventListener('keydown',e=>{if(mode!=='memories')return;if(e.key==='ArrowLeft'){e.preventDefault();changePhoto(-1);}if(e.key==='ArrowRight'){e.preventDefault();changePhoto(1);}});}
function beginParty(){mode='party';epilogueScreen='memories';partyTime=0;photoIndex=0;level=4;m={...freshModel(4),phase:3,coverage:1,toppings:3,lit:true};running=true;paused=false;finished=true;unlocked=5;dialogueQueue=[];activeDialogue=null;particles=[];clearInputs();$('#arena').classList.remove('epilogue','office-bubbles');$('#arena').classList.add('party-scene','sweet-scene');$('#hud').hidden=true;$('#touch').hidden=true;$('#banner').hidden=true;$('#bubble').hidden=true;$('#mission').hidden=true;$('#memory').hidden=true;$('#overlay').hidden=true;$('#party-actions').hidden=false;$('#level-name').textContent='DULCE COMBINACIÓN · ¡FELIZ CUMPLEAÑOS, INDIRA!';resize();save();}
function updateParty(dt){partyTime+=dt;t+=dt;walk+=dt*2;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(!reduced&&Math.random()<dt*7)burst(270+Math.random()*340,195,'#e78eb8',5);particles=particles.filter(p=>{p.x+=p.vx*dt*.45;p.y+=Math.abs(p.vy)*dt+dt*32;p.life-=dt*.5;return p.life>0;});if(partyTime>=8)showMemories();}
