function enterEpilogue(screen){mode=screen;epilogueScreen=screen;running=false;paused=false;finished=true;unlocked=5;$('#arena').classList.remove('party-scene','office-bubbles','celebrating');$('#arena').classList.add('epilogue','sweet-scene');$('#party-actions').hidden=true;$('#hud').hidden=true;$('#touch').hidden=true;$('#banner').hidden=true;$('#bubble').hidden=true;$('#mission').hidden=true;$('#memory').hidden=true;$('#overlay').hidden=false;save();}
function showMemories(){enterEpilogue('memories');$('#level-name').textContent='NUESTROS RECUERDOS · A TU RITMO';$('#overlay').innerHTML='<section class="memory-scene"><span class="epilogue-kicker">LA MEJOR ALIANZA ERA LA NUESTRA</span><h1>Todo lo bonito<br>que nos llevamos.</h1><p class="memory-intro">Mira cada recuerdo con calma. Toca la fotografía para ampliarla.</p><figure id="gallery"><button id="enlarge-photo" class="memory-image" aria-label="Ampliar fotografía"><img id="memory-photo" alt="" decoding="async"></button><figcaption id="memory-count" aria-live="polite"></figcaption></figure><nav class="memory-controls" aria-label="Galería de recuerdos"><button id="photo-prev">← Anterior</button><span>Sin prisa.</span><button id="photo-next">Siguiente →</button></nav><button id="letter-open" class="pink-button">Leer tu felicitación →</button></section>';$('#photo-prev').onclick=()=>changePhoto(-1);$('#photo-next').onclick=()=>changePhoto(1);$('#enlarge-photo').onclick=()=>{if(photoSwiped){photoSwiped=false;return;}refreshLightbox();$('#photo-lightbox').showModal();};$('#letter-open').onclick=showLetter;bindPhotoSwipe();updatePhoto();}
function updatePhoto(){photoIndex=clamp(photoIndex,0,RECUERDOS.length-1);const item=RECUERDOS[photoIndex],img=$('#memory-photo');if(img){img.src=item.src;img.alt=item.alt;img.classList.remove('photo-arrive');void img.offsetWidth;img.classList.add('photo-arrive');}if($('#memory-count'))$('#memory-count').textContent=`Recuerdo ${photoIndex+1} de ${RECUERDOS.length} · José e Indira`;if($('#photo-prev'))$('#photo-prev').disabled=photoIndex===0;if($('#photo-next'))$('#photo-next').disabled=photoIndex===RECUERDOS.length-1;if($('#photo-lightbox').open)refreshLightbox();save();}
function changePhoto(delta){photoIndex=clamp(photoIndex+delta,0,RECUERDOS.length-1);updatePhoto();}
function refreshLightbox(){const item=RECUERDOS[photoIndex];$('#lightbox-photo').src=item.src;$('#lightbox-photo').alt=item.alt;$('#lightbox-count').textContent=`${photoIndex+1} / ${RECUERDOS.length}`;$('#lightbox-prev').disabled=photoIndex===0;$('#lightbox-next').disabled=photoIndex===RECUERDOS.length-1;}
function bindPhotoSwipe(){const el=$('#enlarge-photo');let down=null;el.onpointerdown=e=>{down={x:e.clientX,y:e.clientY};photoSwiped=false;};el.onpointerup=e=>{if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;down=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.4){photoSwiped=true;changePhoto(dx<0?1:-1);}};el.onpointercancel=()=>down=null;}
