function syncGameAudio(){try{window.GameAudio?.sync({mode,level,paused,pendingLevel,mailIndex,x:player.x,y:player.y,hit,docs:m.docs?.length||0,step:m.step||0,cycles:m.cycles||0,credit:m.creditAmount||0,cargo:m.cargo?.map(c=>c.state),ids:m.cards?.length||0,lit:!!m.lit,rescueTime,nearSeal:level===3&&!!m.seals?.some(s=>dist(player,s)<240),dialogue:!!activeDialogue||!!m.speeches?.length});}catch{}}
function frame(now){const dt=Math.min(.05,last?(now-last)/1000:0);last=now;if(running&&!paused){if(mode==='party')updateParty(dt);else if(mode==='preamble')updatePreamble(dt);else if(mode==='mail')updateMail(dt);else if(mode==='mission')storyClock+=dt;else if(mode==='chat')updateChat(dt);else if(mode==='rescue')updateRescue(dt);else update(dt);}else if(finished){storyClock+=dt;advanceDialogue();}if(mode==='party')renderParty();else if(mode==='rescue')renderRescue();else if(mode!=='memories'&&mode!=='letter')render();renderWorldSpeech();renderTransitionStatus();const layoutBounds=canvas.getBoundingClientRect();if(Math.abs(canvas.width/dpr-vw)>.1||Math.abs(vh-vw*layoutBounds.height/layoutBounds.width)>.5)resize();updateActionUI();syncGameAudio();requestAnimationFrame(frame);}
